import csv, json
from datetime import date

AUDIT_DATE = date(2026, 3, 31)

def load_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

accounts = {a['account_id']: a for a in load_csv('/app/input/client_accounts.csv')}
licences = {l['license_id']: l for l in load_csv('/app/input/licensed_property_register.csv')}
requests = load_csv('/app/input/composite_request_log.csv')

def parse_date(s):
    y, m, d = s.split('-')
    return date(int(y), int(m), int(d))

def lic_covers(req, lic_id, use_type):
    """§2: does licence cover the request for the given use_type?"""
    if lic_id == 'none' or lic_id == '':
        return False
    lic = licences.get(lic_id)
    if lic is None:
        return False
    # (1) id appears in register -> yes (we got it)
    # (2) license_type matches use
    if lic['license_type'] != use_type:
        return False
    # (3) covers_distribution lists intended_distribution or is 'all'
    dists = lic['covers_distribution'].split(';')
    dists = [d.strip() for d in dists]
    if dists == ['all']:
        pass
    elif req['intended_distribution'] not in dists:
        return False
    # (4) valid_until on or after audit date
    if parse_date(lic['valid_until']) < AUDIT_DATE:
        return False
    return True

def account_clears(acc, distribution):
    """§6: account clears the channel"""
    if acc['agreement_status'] != 'active':
        return False
    covers = [c.strip() for c in acc['master_agreement_covers'].split(';')]
    return distribution in covers

FINDING_ORDER = [
    'UNLICENSED_CHARACTER_USE',
    'THIRD_PARTY_BACKGROUND_UNLICENSED',
    'MISSING_MINOR_CONSENT',
    'COMMERCIAL_DISTRIBUTION_FLAG',
    'ALTERATION_DISCLOSURE_MISSING',
]

audit = {}  # request_id -> list of findings
records = {}  # request_id -> dict of deciding records per finding

for req in requests:
    rid = req['request_id']
    findings = []
    rec = {}

    # §3 Licensed-character use
    if req['character_property'] != 'none':
        cleared_by_lic = lic_covers(req, req['character_license_id'], 'character')
        personal = req['intended_distribution'] == 'personal_only'
        if not (cleared_by_lic or personal):
            findings.append('UNLICENSED_CHARACTER_USE')
            if req['character_license_id'] in ('none',''):
                rec['UNLICENSED_CHARACTER_USE'] = 'no licence on request'
            else:
                lic = licences.get(req['character_license_id'])
                if lic is None:
                    rec['UNLICENSED_CHARACTER_USE'] = f"{req['character_license_id']} not in register"
                else:
                    # why doesn't it cover?
                    reasons=[]
                    if lic['license_type']!='character':
                        reasons.append(f"{req['character_license_id']} license_type={lic['license_type']}")
                    dists=[d.strip() for d in lic['covers_distribution'].split(';')]
                    if dists!=['all'] and req['intended_distribution'] not in dists:
                        reasons.append(f"{req['character_license_id']} covers {lic['covers_distribution']} not {req['intended_distribution']}")
                    if parse_date(lic['valid_until']) < AUDIT_DATE:
                        reasons.append(f"{req['character_license_id']} valid_until {lic['valid_until']} (before audit date)")
                    rec['UNLICENSED_CHARACTER_USE'] = '; '.join(reasons) if reasons else req['character_license_id']

    # §4 Third-party backgrounds
    bs = req['background_source']
    if bs == 'customer_original':
        pass
    elif bs == 'third_party_unlicensed':
        findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
        rec['THIRD_PARTY_BACKGROUND_UNLICENSED'] = 'background_source=third_party_unlicensed (own record)'
    elif bs == 'third_party_licensed':
        if not lic_covers(req, req['background_license_id'], 'background'):
            findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
            if req['background_license_id'] in ('none',''):
                rec['THIRD_PARTY_BACKGROUND_UNLICENSED'] = 'no background licence on request'
            else:
                lic = licences.get(req['background_license_id'])
                if lic is None:
                    rec['THIRD_PARTY_BACKGROUND_UNLICENSED'] = f"{req['background_license_id']} not in register"
                else:
                    reasons=[]
                    if lic['license_type']!='background':
                        reasons.append(f"{req['background_license_id']} license_type={lic['license_type']}")
                    dists=[d.strip() for d in lic['covers_distribution'].split(';')]
                    if dists!=['all'] and req['intended_distribution'] not in dists:
                        reasons.append(f"{req['background_license_id']} covers {lic['covers_distribution']} not {req['intended_distribution']}")
                    if parse_date(lic['valid_until']) < AUDIT_DATE:
                        reasons.append(f"{req['background_license_id']} valid_until {lic['valid_until']} (before audit date)")
                    rec['THIRD_PARTY_BACKGROUND_UNLICENSED'] = '; '.join(reasons) if reasons else req['background_license_id']

    # §5 Minor consent
    if req['subject_is_minor'] == 'True':
        ct = req['minor_consent_type']
        reasons=[]
        if ct == 'none':
            reasons.append('consent type none (not present)')
        else:
            if parse_date(req['minor_consent_valid_until']) < AUDIT_DATE:
                reasons.append(f"consent valid_until {req['minor_consent_valid_until']} (before audit date)")
            dist = req['intended_distribution']
            if ct == 'basic' and dist not in ('personal_only','client_internal'):
                reasons.append(f"basic consent does not cover {dist}")
        if reasons:
            findings.append('MISSING_MINOR_CONSENT')
            rec['MISSING_MINOR_CONSENT'] = '; '.join(reasons)

    # §6 Commercial distribution routing
    dist = req['intended_distribution']
    if dist in ('social_public','print_for_sale'):
        acc = accounts[req['account_id']]
        if not account_clears(acc, dist):
            findings.append('COMMERCIAL_DISTRIBUTION_FLAG')
            if acc['agreement_status'] != 'active':
                rec['COMMERCIAL_DISTRIBUTION_FLAG'] = f"account {req['account_id']} agreement {acc['agreement_status']} (lapsed covers nothing)"
            else:
                covers=[c.strip() for c in acc['master_agreement_covers'].split(';')]
                rec['COMMERCIAL_DISTRIBUTION_FLAG'] = f"account {req['account_id']} active but covers {acc['master_agreement_covers']} (not {dist})"

    # §7 Alteration disclosure
    if req['alteration_level']=='substantive' and dist in ('social_public','print_for_sale'):
        if req['alteration_disclosure_on_file'] != 'True':
            findings.append('ALTERATION_DISCLOSURE_MISSING')
            rec['ALTERATION_DISCLOSURE_MISSING'] = 'substantive + public/paid, disclosure not on file'

    # order findings per FINDING_ORDER
    ordered = [f for f in FINDING_ORDER if f in findings]
    audit[rid] = ordered
    records[rid] = rec

# Print per-request
print("=== PER REQUEST ===")
for req in requests:
    rid=req['request_id']
    fs = audit[rid]
    s = '|'.join(fs) if fs else 'none'
    print(f"{rid} ({req['account_id']}, {req['intended_distribution']}, char={req['character_property']}, bgsrc={req['background_source']}): {s}")
    for f in fs:
        print(f"    {f}: {records[rid][f]}")

# Account summary
print("\n=== ACCOUNT SUMMARY ===")
acc_summary={}
for acc_id, acc in accounts.items():
    reqs = [r for r in requests if r['account_id']==acc_id]
    flagged = [r for r in reqs if audit[r['request_id']]]
    escalate = 'none'
    if len(flagged) >= 2:
        escalate = 'ESCALATION_REQUIRED'
    elif any(len(audit[r['request_id']])>=3 for r in reqs):
        escalate = 'ESCALATION_REQUIRED'
    acc_summary[acc_id]=(acc['account_type'], len(reqs), len(flagged), escalate)
    print(f"{acc_id} {acc['account_type']} count={len(reqs)} flagged={len(flagged)} esc={escalate}")

# Stats
flagged_count = sum(1 for r in requests if audit[r['request_id']])
compliant_count = len(requests)-flagged_count
finding_total = sum(len(audit[r['request_id']]) for r in requests)
def count_finding(f):
    return sum(1 for r in requests if f in audit[r['request_id']])
char_count=count_finding('UNLICENSED_CHARACTER_USE')
bg_count=count_finding('THIRD_PARTY_BACKGROUND_UNLICENSED')
consent_count=count_finding('MISSING_MINOR_CONSENT')
comm_count=count_finding('COMMERCIAL_DISTRIBUTION_FLAG')
disc_count=count_finding('ALTERATION_DISCLOSURE_MISSING')
escalated=sum(1 for a in acc_summary if acc_summary[a][3]=='ESCALATION_REQUIRED')

print("\n=== STATS ===")
print(f"request_count={len(requests)}")
print(f"account_count={len(accounts)}")
print(f"flagged_count={flagged_count}")
print(f"compliant_count={compliant_count}")
print(f"finding_total={finding_total}")
print(f"character_count={char_count}")
print(f"background_count={bg_count}")
print(f"consent_count={consent_count}")
print(f"commercial_count={comm_count}")
print(f"disclosure_count={disc_count}")
print(f"escalated_accounts={escalated}")

# Personal-use allowance clears (§3)
print("\n=== PERSONAL-USE ALLOWANCE CLEARS (character, personal_only) ===")
for req in requests:
    if req['character_property']!='none' and req['intended_distribution']=='personal_only':
        print(f"{req['request_id']}: {req['character_property']} ({req['character_license_id']})")

# Cleared by licence for §3
print("\n=== §3 CLEARED BY LICENCE ===")
for req in requests:
    if req['character_property']!='none':
        if lic_covers(req, req['character_license_id'], 'character'):
            print(f"{req['request_id']}: {req['character_property']} cleared by {req['character_license_id']}")

# Cleared by licence for §4
print("\n=== §4 CLEARED BY LICENCE ===")
for req in requests:
    if req['background_source']=='third_party_licensed':
        if lic_covers(req, req['background_license_id'], 'background'):
            print(f"{req['request_id']}: bg {req['background_license_id']} covers")

# Lapsed accounts
print("\n=== LAPSED AGREEMENTS ===")
for acc_id, acc in accounts.items():
    if acc['agreement_status']=='lapsed':
        print(f"{acc_id} {acc['account_name']} covers={acc['master_agreement_covers']} (lapsed)")
