import csv, json
from datetime import date

AUDIT_DATE = date(2026, 3, 31)

def load_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))

accounts = {a['account_id']: a for a in load_csv('/app/input/client_accounts.csv')}
accounts_order = [a['account_id'] for a in load_csv('/app/input/client_accounts.csv')]
licences = {l['license_id']: l for l in load_csv('/app/input/licensed_property_register.csv')}
requests = load_csv('/app/input/composite_request_log.csv')

def parse_date(s):
    y, m, d = s.split('-')
    return date(int(y), int(m), int(d))

def lic_covers(req, lic_id, use_type):
    if lic_id in ('none',''):
        return False
    lic = licences.get(lic_id)
    if lic is None:
        return False
    if lic['license_type'] != use_type:
        return False
    dists = [d.strip() for d in lic['covers_distribution'].split(';')]
    if dists != ['all'] and req['intended_distribution'] not in dists:
        return False
    if parse_date(lic['valid_until']) < AUDIT_DATE:
        return False
    return True

def account_clears(acc, distribution):
    if acc['agreement_status'] != 'active':
        return False
    covers = [c.strip() for c in acc['master_agreement_covers'].split(';')]
    return distribution in covers

FINDING_ORDER = [
    'UNLICENSED_CHARACTER_USE',
    'THIRD_PARTY_BACKGROUND_UNLICENSED',
    'MISSING_MINOR_CONSENT',
    'COMMERCIAL_DISTRIBUTION_FLAG',
    'ALTERATION_DISCLOSURE_MISSING',
]

audit = {}
for req in requests:
    rid = req['request_id']
    findings = []
    if req['character_property'] != 'none':
        cleared_by_lic = lic_covers(req, req['character_license_id'], 'character')
        personal = req['intended_distribution'] == 'personal_only'
        if not (cleared_by_lic or personal):
            findings.append('UNLICENSED_CHARACTER_USE')
    bs = req['background_source']
    if bs == 'third_party_unlicensed':
        findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
    elif bs == 'third_party_licensed':
        if not lic_covers(req, req['background_license_id'], 'background'):
            findings.append('THIRD_PARTY_BACKGROUND_UNLICENSED')
    if req['subject_is_minor'] == 'True':
        ct = req['minor_consent_type']
        fail = False
        if ct == 'none':
            fail = True
        else:
            if parse_date(req['minor_consent_valid_until']) < AUDIT_DATE:
                fail = True
            dist = req['intended_distribution']
            if ct == 'basic' and dist not in ('personal_only','client_internal'):
                fail = True
        if fail:
            findings.append('MISSING_MINOR_CONSENT')
    dist = req['intended_distribution']
    if dist in ('social_public','print_for_sale'):
        acc = accounts[req['account_id']]
        if not account_clears(acc, dist):
            findings.append('COMMERCIAL_DISTRIBUTION_FLAG')
    if req['alteration_level']=='substantive' and dist in ('social_public','print_for_sale'):
        if req['alteration_disclosure_on_file'] != 'True':
            findings.append('ALTERATION_DISCLOSURE_MISSING')
    ordered = [f for f in FINDING_ORDER if f in findings]
    audit[rid] = ordered

# composite_request_audit.csv
with open('/app/composite_request_audit.csv','w',newline='') as f:
    w = csv.writer(f)
    w.writerow(['request_id','finding'])
    for req in requests:
        rid = req['request_id']
        fs = audit[rid]
        w.writerow([rid, '|'.join(fs) if fs else 'none'])

# account_summary.csv
acc_rows = []
for acc_id in accounts_order:
    acc = accounts[acc_id]
    reqs = [r for r in requests if r['account_id']==acc_id]
    flagged = [r for r in reqs if audit[r['request_id']]]
    escalate = 'none'
    if len(flagged) >= 2 or any(len(audit[r['request_id']])>=3 for r in reqs):
        escalate = 'ESCALATION_REQUIRED'
    acc_rows.append([acc_id, acc['account_type'], len(reqs), len(flagged), escalate])
with open('/app/account_summary.csv','w',newline='') as f:
    w = csv.writer(f)
    w.writerow(['account_id','account_type','request_count','flagged_requests','escalation'])
    for row in acc_rows:
        w.writerow(row)

# results.json
flagged_count = sum(1 for r in requests if audit[r['request_id']])
finding_total = sum(len(audit[r['request_id']]) for r in requests)
def count_finding(f):
    return sum(1 for r in requests if f in audit[r['request_id']])
escalated = sum(1 for a in accounts_order if acc_rows[[r[0] for r in acc_rows].index(a)][4]=='ESCALATION_REQUIRED')
results = {
    'request_count': len(requests),
    'account_count': len(accounts),
    'flagged_count': flagged_count,
    'compliant_count': len(requests)-flagged_count,
    'finding_total': finding_total,
    'character_count': count_finding('UNLICENSED_CHARACTER_USE'),
    'background_count': count_finding('THIRD_PARTY_BACKGROUND_UNLICENSED'),
    'consent_count': count_finding('MISSING_MINOR_CONSENT'),
    'commercial_count': count_finding('COMMERCIAL_DISTRIBUTION_FLAG'),
    'disclosure_count': count_finding('ALTERATION_DISCLOSURE_MISSING'),
    'escalated_accounts': escalated,
}
with open('/app/results.json','w') as f:
    json.dump(results, f, indent=2)
    f.write('\n')

print("Deliverables written.")
print(json.dumps(results, indent=2))
